import hashlibfrom cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modesfrom cryptography.hazmat.backends import default_backendimport binascii# 核心配置（严格16字节，已验证）AES_KEY = b"Your16ByteKey123"  # 16字节（16个字符）AES_IV =  b"Your16ByteIV5678"  # 16字节（16个字符）def aes_encrypt_to_uuid(plaintext):    """    通过AES加密生成128位UUID格式的特征码    :param plaintext: 待加密的原始内容（如设备MAC/SN，字符串）    :return: 符合格式的UUID字符串（如beb5483e-36e1-4688-b7f5-ea07361b26a8）    """    try:        # 1. 预处理明文：补位到16字节倍数（AES CBC模式要求）        plaintext_bytes = plaintext.encode('utf-8')        padding_len = 16 - (len(plaintext_bytes) % 16)        # PKCS7补位（和解密逻辑对齐）        padded_plaintext = plaintext_bytes + bytes([padding_len] * padding_len)        print(f"加密前明文（补位后）：{padded_plaintext.hex()}")        # 2. AES-128-CBC加密（输出密文长度=明文长度）        cipher = Cipher(algorithms.AES(AES_KEY), modes.CBC(AES_IV), backend=default_backend())        encryptor = cipher.encryptor()        ciphertext = encryptor.update(padded_plaintext) + encryptor.finalize()        print(f"加密后密文（完整）：{ciphertext.hex()}")        # 3. 取前16字节密文（保证UUID是128位），转32位小写16进制字符串        ciphertext_16 = ciphertext[:16]        hex_str = binascii.hexlify(ciphertext_16).decode('utf-8').lower()        print(f"前16字节密文转16进制：{hex_str}")        # 4. 按UUID格式分段：8-4-4-4-12        uuid_str = f"{hex_str[:8]}-{hex_str[8:12]}-{hex_str[12:16]}-{hex_str[16:20]}-{hex_str[20:32]}"        return uuid_str    except Exception as e:        print(f"加密出错：{type(e).__name__} - {e}")        return Nonedef aes_decrypt_uuid(uuid_str, expected_plaintext_prefix):    """    APP端解密验证UUID是否为目标设备生成    :param uuid_str: 待验证的UUID    :param expected_plaintext_prefix: 预期明文前缀    :return: True=是目标UUID，False=不是    """    try:        # 1. 去掉UUID分隔符，还原32位16进制字符串        hex_str = uuid_str.replace("-", "")        if len(hex_str) != 32:            print(f"UUID格式错误：16进制字符串长度={len(hex_str)}（需32）")            return False        print(f"解密前16进制字符串：{hex_str}")        # 2. 转16字节密文        ciphertext = binascii.unhexlify(hex_str)        print(f"还原后的密文：{ciphertext.hex()}")        # 3. AES解密        cipher = Cipher(algorithms.AES(AES_KEY), modes.CBC(AES_IV), backend=default_backend())        decryptor = cipher.decryptor()        plaintext_padded = decryptor.update(ciphertext) + decryptor.finalize()        print(f"解密后带补位的明文：{plaintext_padded.hex()} | 原始字节：{plaintext_padded}")        # # 4. 去除PKCS7补位（关键：处理补位为16的情况）        # # padding_len = plaintext_padded[-1]        # padding_len = len(plaintext_padded)        # # 边界处理：如果补位是16，说明明文刚好是16的倍数，要去掉最后16字节        # if padding_len == 16:        #     plaintext = plaintext_padded[:-16].decode('utf-8')        # else:        #     plaintext = plaintext_padded[:-padding_len].decode('utf-8')        # print(f"去除补位后的明文：{plaintext}")        plaintext = plaintext_padded.decode('utf-8')        # 5. 验证明文是否符合预期        result = plaintext.startswith(expected_plaintext_prefix)        print(f"验证明文前缀[{expected_plaintext_prefix}]：{result}")        return result    except Exception as e:        print(f"解密出错：{type(e).__name__} - {e}")        return False# 测试示例：生成+验证UUIDif __name__ == "__main__":    # 待加密的原始内容（每个设备唯一）    device_unique_content = "AA:BB:CC:DD:EE:FF-SN2026021100001"    print(f"原始明文：{device_unique_content}\n")    # 1. 生成UUID    dynamic_uuid = aes_encrypt_to_uuid(device_unique_content)    print(f"\nAES加密生成的UUID：{dynamic_uuid}\n")    # 2. APP端验证UUID    if dynamic_uuid:        is_target = aes_decrypt_uuid(dynamic_uuid, "AA:BB:CC")        print(f"\n是否为目标设备UUID：{is_target}")  # 现在会输出True    else:        print("UUID生成失败，无法验证")